/* eslint-disable react/prop-types */
import React, { useEffect, useState, useMemo } from 'react';
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import {
  Card,
  Stack,
  Button,
  Popover,
  MenuItem,
  Typography,
  IconButton,
  TablePagination,
  Grid,
  Box,
} from '@mui/material';
import AddBoxIcon from '@mui/icons-material/AddBox';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import { axios } from '../../utils/axios';
import { updateUrlParams } from '../../utils/urlUtilis';
import { useMyContext } from '../provider';
import Iconify from '../../components/iconify';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import Scrollbar from '../../components/scrollbar/Scrollbar';
import { UserListToolbar } from '../../sections/@dashboard/user';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import { IMAGE_URL } from '../../utils/config';
import Label from '../../components/label/Label';
import useResponsive from '../../hooks/useResponsive';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

const EditGallery = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);
  const collection = queryParams.get('collection');
  const [totalCount, setTotalCount] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [search, setsearch] = useState(queryParams.get('search') || '');
  const [collectionDatas, setCollectionDatas] = useState([]);
  const [opensDeleteModal, setOpensDeleteModal] = useState(false);
  const [filters, setFilters] = useState({})

  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')
  const [images, setImages] = useState([]);
  const [searchParams, setSearcParams] = useSearchParams()
  const [isLoading, setIsLoading] = useState(true);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let url = `/module/gallery/images?collection=${collection}`;
      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });
      const response = await axios.get(url);
      if (response?.status === 200) {
        setCollectionDatas(response?.data?.data?.galleryImage);
        setTotalCount(response?.data?.totalCount ? response?.data?.totalCount : 0);

      }
    } catch (error) {
      if (error.response.status === 400) {
        setCollectionDatas([]);
        setTotalCount(0);
      } else {
        GenerateToastConfig(error.response.message || error.message);
      }
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, search, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    const newLimit = parseInt(event.target.value, 10);
    setRowsPerPage(newLimit);
    setPage(1);
  };

  const handleFilterByName = (event) => {
    const filterValue = event.target.value;
    setsearch(filterValue);
    queryParams.set('search', filterValue);
    window.history.pushState(null, '', `?${queryParams.toString()}`);
  };

  const ActionComponent = (cell) => {
    const value = cell?.getValue();
    console.log(value);

    const original = cell?.row?.original;
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    const viewImage = (path) => {
      const imageUrl = `${IMAGE_URL}${path}`;
      window.open(imageUrl, '_blank');
    };


    const deleteModal = (ids) => {
      sessionStorage.setItem('rowGalleryImage', ids);
      setOpensDeleteModal(true);
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >
          <MenuItem onClick={() => viewImage(original?.path)}>
            <Iconify icon={'carbon:view'} sx={{ mr: 2 }} /> View
          </MenuItem>
          {!original?.status && <MenuItem onClick={() => deleteModal(original?._id)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>}
        </Popover>
      </>
    );
  }

  const columns = [
    {
      header: i18?.ACCOUNTSTITLE?.COLLECTION_NAME || "Collection Name",
      id: "collection",
      accessorKey: "collectionName",
      showFilter: false,
      cell: ({ row }) => <span>{row?.original?.collectionName}</span>,
    },
    {
      header: i18?.ACCOUNTSTITLE?.IMAGE || "Image",
      id: "path",
      accessorKey: "path",
      cell: ({ row }) => (
        <img
          src={`${IMAGE_URL}${row?.original?.path}`}
          alt="Gallery"
          style={{ width: '50px', height: '50px', objectFit: 'cover' }}
        />
      ),
    },
    {
      header: i18?.ACCOUNTSTITLE?.CREATEDAT || "Created At",
      id: "addedAt",
      accessorKey: "addedAt",
      showFilter: false,
      cell: ({ row }) => (
        <span>{DateFormat(row?.original?.addedAt)}</span>
      ),
    },
    {
      header: i18?.ACCOUNTSTITLE?.ACTION || "Action",
      id: "action",
      accessorKey: "_id",
      cell: ActionComponent
    },
  ];

  const deleteCollectionImage = async () => {
    const imageId = sessionStorage.getItem('rowGalleryImage');
    try {
      const res = await axios.delete(`module/gallery/images?imageIds=${imageId}`);
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'info');
        setOpensDeleteModal(false);
        fetchData();
      } else {
        GenerateToastConfig(res?.data?.message);
      }
    } catch (error) {
      GenerateToastConfig(error?.response?.data?.message);
    }
  };

  // const handleImageChange = (uploadedImages) => {
  //   setImages(uploadedImages);
  // };
  const handleOpenAddGallery = () => {
    const collection = searchParams.get('collection')
    navigate(`/dashboard/addImages?collection=${collection}`)
  }

  const backToGallery = () => {
    navigate('/dashboard/gallery');
  };

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  return (
    <>
      <Grid container sx={{ padding: '10px 0px', margin: '10px 0px' }}>
        <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <Box
              sx={{
                width: '37px',
                height: '37px',
                background: '#FF5A60',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: '50%',
                cursor: 'pointer'
              }}
              onClick={backToGallery}
            >
              <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
            </Box>
            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {/* {i18?.ACCOUNTSTITLE?.ADD_COLLECTION || `View Images`} */}
              {
                collectionDatas[0]?.collectionName ? collectionDatas[0]?.collectionName?.charAt(0).toUpperCase() + collectionDatas[0].collectionName.slice(1) : ''
              }
            </Typography>

          </Box>
          {/* <Stack direction='row' alignItems="center" >
            <UserListToolbar
              // numSelected={selected.length}
              // filterName={filterName}
              onFilterName={handleFilterByName}
              search={search}
              setsearch={setsearch}
            />
          </Stack> */}
          <Button sx={{
            padding: "9px 28px"
          }} variant="contained" onClick={handleOpenAddGallery} startIcon={<AddBoxIcon />}>
            {i18?.ACCOUNTSTITLE?.ADD_IMAGES || "Add Images"}
          </Button>
        </Grid>
      </Grid>

      <Card sx={{ padding: '0px 0px', margin: '0px 0px', overflowX: 'auto' }}>
        {/* {isMobile && <UserListToolbar
          // numSelected={selected.length}
          // filterName={filterName}
          onFilterName={handleFilterByName}
          search={search}
          setsearch={setsearch}
        />} */}
        <Scrollbar>
          {/* <TanstackTable data={data} columns={columns} loading={loading}/> */}
          <TanstackTableV8
            data={collectionDatas}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange}
          />
        </Scrollbar>
      </Card>

      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || 0}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />

      <DeleteModal
        isDeleteOpen={opensDeleteModal}
        handleClose={() => setOpensDeleteModal(false)}
        handleDelete={deleteCollectionImage}
      />
    </>
  );
};

export default EditGallery;
